from abc import ABCMeta, abstractmethod
import six
import logging

from .builder import Builder
from .bip.classical_gnb import ClassicalGnbBipCollectorConfigurator
from .bip.cloud_gnb import CloudBipCollectorConfigurator
from .emil.classical_gnb import ClassicalGnbEmilCollectorConfigurator
from .emil.cloud_gnb import CloudGnbEmilCollectorConfigurator
from .protocols.classical_gnb import ClassicalGnbProtocolsCollectorConfigurator
from .pmcounters.classical_gnb import ClassicalGnbPmcountersCollectorConfigurator
from .pmcounters.cloud_gnb import CloudGnbPmcountersCollectorConfigurator
from .protocols.cloud_gnb import CloudGnbProtocolsCollectorConfigurator
from .snapshot.cloud_gnb import CloudGnbSnapshotCollectorConfigurator
from .syslog.classical_gnb import ClassicalGnbSyslogCollectorConfigurator
from .syslog.cloud_gnb import CloudGnbSyslogCollectorConfigurator
from .uplane_trace.classical_gnb import ClassicalGnbUplaneTraceCollectorConfigurator
from .uplane_trace.cloud_gnb import CloudGnbUplaneTraceCollectorConfigurator
from .snapshot.classical_gnb import ClassicalGnbSnapshotCollectorConfigurator
from .ocp.cloud_gnb import CloudGnbOcpCollectorConfigurator
from .screl.classical_gnb import ClassicalGnbScrelCollectorConfigurator
from .screl.cloud_gnb import CloudGnbScrelCollectorConfigurator

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@six.add_metaclass(ABCMeta)
class GnbBuilder(Builder):
    ne_type = "gnb"

    @abstractmethod
    def add_syslog(self, ne_log_name, ne_log_configuration):
        pass

    @abstractmethod
    def add_emil(self, ne_log_name, ne_log_configuration):
        pass

    @abstractmethod
    def add_bip(self, ne_log_name, ne_log_configuration):
        pass

    @abstractmethod
    def add_protocols(self, ne_log_name, ne_log_configuration):
        pass

    @abstractmethod
    def add_snapshot(self, ne_log_name, ne_log_configuration):
        pass

    @abstractmethod
    def add_pmcounters(self, ne_log_name, ne_log_configuration):
        pass

    @abstractmethod
    def add_ocp(self, ne_log_name, ne_log_configuration):
        pass

    @abstractmethod
    def add_uplane_trace(self, ne_log_name, ne_log_configuration):
        pass

    @abstractmethod
    def add_screl(self, ne_log_name, ne_log_configuration):
        pass

class ClassicalGnbBuilder(
        ClassicalGnbSyslogCollectorConfigurator,
        ClassicalGnbEmilCollectorConfigurator,
        ClassicalGnbBipCollectorConfigurator,
        ClassicalGnbProtocolsCollectorConfigurator,
        ClassicalGnbPmcountersCollectorConfigurator,
        ClassicalGnbUplaneTraceCollectorConfigurator,
        ClassicalGnbSnapshotCollectorConfigurator,
        ClassicalGnbScrelCollectorConfigurator,
        GnbBuilder):

    def __init__(
            self,
            tl_config_information_provider,
            sbts_oam_information_provider,
            **kwargs):
        super().__init__(**kwargs)
        self.tl_config_information_provider = tl_config_information_provider
        self.sbts_oam_information_provider = sbts_oam_information_provider
        self.add_prerequisite(sbts_oam_information_provider)

    def add_ocp(self, ne_log_name, ne_log_configuration):
        logger.warning("Log for OCP is not implemented for classical gnb - it is a pure all in cloud log!")
        self._collector_configuration_data.append(
            {
                'name': ne_log_name,
                'type': 'log_collection_dummy'})


class CloudGnbBuilder(
        CloudGnbProtocolsCollectorConfigurator,
        CloudGnbSnapshotCollectorConfigurator,
        CloudGnbSyslogCollectorConfigurator,
        CloudGnbEmilCollectorConfigurator,
        CloudBipCollectorConfigurator,
        CloudGnbOcpCollectorConfigurator,
        CloudGnbPmcountersCollectorConfigurator,
        CloudGnbUplaneTraceCollectorConfigurator,
        CloudGnbScrelCollectorConfigurator,
        GnbBuilder):

    def __init__(
            self,
            tl_config_information_provider,
            k8s_information_provider,
            vcu_oam_information_provider,
            vdu_oam_information_providers,
            **kwargs):
        super().__init__(**kwargs)
        self.tl_config_information_provider = tl_config_information_provider
        self.k8s_information_provider = k8s_information_provider
        self.vcu_oam_information_provider = vcu_oam_information_provider
        self.add_prerequisite(vcu_oam_information_provider)
        self.vdu_oam_information_providers = vdu_oam_information_providers
        for vdu_oam_information_provider in vdu_oam_information_providers:
            self.add_prerequisite(vdu_oam_information_provider)

